"""Report measured branch counters and language quality without inventing success."""
import hashlib,json,pathlib
ROOT=pathlib.Path(__file__).resolve().parent

def read(p):return json.loads(p.read_text())
def main():
 audit=read(ROOT/'optimizer-audit.json');comparison=read(ROOT/'comparison.json');choice=read(ROOT/'vocabulary-choice.json');candidate=ROOT/f"word-{choice['wordMerges']}-continue-10000";metrics=read(candidate/'metrics.json');result=read(candidate/'result.json')
 lines=['# Raw Japanese short word BPE results','',f"Natural Japanese established: **{comparison['naturalLanguageEstablished']}**. Completed updates: **{audit['actualCompletedUpdatesThisRound']:,}**, comprising two distinct 1,000-update pilots and 10,000 main updates. Selected weight lineage: **{audit['selectedWeightLineageUpdates']:,}**. Planned counts and updates on the rejected pilot are not represented as selected lineage.",'','## Canonical held-text likelihood','', '| Stage | Word rules | Completed updates | Initial NLL/byte | Best NLL/byte | Selected step |','|---|---:|---:|---:|---:|---:|']
 for stage in [*audit['pilots'],audit['main']]:
  word=int(stage['run'].split('-')[1]);lines.append(f"| {stage['run']} | {word} | {stage['completedUpdates']} | {stage['initialValidationNllPerByte']:.6f} | {stage['bestValidationNllPerByte']:.6f} | {stage['bestStep']} |")
 lines+=['',f"Vocabulary {choice['wordMerges']} selected by canonical VAL NLL/UTF8 byte only, before generation. Token perplexity across the two vocabularies is not a fair selection metric. The main0 raw baseline already contains {choice['selectedPilotStep']} selected pilot updates, with fresh empty main optimizer state. It adds zero main updates.",'','| Site | Main0 NLL/byte | Selected main NLL/byte |','|---|---:|---:|']
 first=metrics['history'][0]['validation']['sites'];selected=next(row['validation']['sites'] for row in metrics['history'] if row['step']==result['bestStep'])
 for site in sorted(first):lines.append(f"| {site} | {first[site]['nllPerUtf8Byte']:.6f} | {selected[site]['nllPerUtf8Byte']:.6f} |")
 lines+=['','## Raw continuations','', '| Model | Scope | Sentence passes | Nonloop | Meaningful full outputs | Language gate |','|---|---|---:|---:|---:|---|']
 for name,run in comparison['runs'].items():
  for scope,s in run['scopes'].items():lines.append(f"| {name} | {scope} | {s['passed']}/{s['total']} | {s['fullOutputNonLoop']}/{s['total']} | {s['fullOutputMeaningful']}/{s['total']} | {s['gatePassed']} |")
 lines+=['','All17, inherited13 and original9 must pass separately in narrative and modern prose. Full meaning is required in addition to grammar, sustained connection and absence of loops. Short first-sentence closure does not establish coherence. These are assistant manual judgments, not independent human assessment. Unmodified raw outputs, every token ID and Python/JS parity evidence are retained. Unsupported factual claims are not certified as true.','', 'No TEST34 generation, QA/instruction tuning or public model replacement occurred. No Wikipedia, external weights/tokenizer/API, teacher text, retrieval, fixed response or output rewriting was used.','', '## Reproducibility and limits','', f"Own random-initialized ancestry is verified through round8; all source/data/policy hashes are fixed. Every AdamW counter equals its actual branch count. Model weights and optimizer moments are FP32; training activations use BF16, CPU2. Training corpus, word vocabulary and sampling differ from round8, so cross-round changes cannot be assigned to a single factor.",'',f"Round3 onward confirmed completed branch counters: {audit['round3OnwardConfirmedCompletedUpdates']:,}; physical execution lower bound: {audit['round3OnwardPhysicalUpdatesLowerBound']:,}, including >=100 discarded round8 updates. Some unlogged round8 discarded updates remain unknown. These are not whole-lifetime totals. Any later interruption/recovery must be audited separately before publication.",'', 'Exact trimmed paragraph audit found56short paragraph types shared between TRAIN and held folds (128held occurrences), and zero shared paragraph types of at least80characters. Frequent browser/PDF notices also remain. These limits are documented in corpus-quality-diagnostic.json; they are not retroactively removed from this frozen experiment. Source-preserving duplicate TRAIN segmentations do not enlarge independent text coverage. Exact-title/long-paragraph grouping does not rule out fuzzy or short overlap. Generation timings are recorded CPU measurements, not controlled browser speed comparisons. Fewer subword tokens does not by itself prove faster or better answers.','',f"Selected checkpoint SHA256: `{result['checkpointSha256']}`.",'']
 lines+=['## Numerical comparison failure','', 'The frozen evaluate_validation.py pipeline exited with status1 because trained full greedy sequence parity was false:16/17 Python/JS continuations matched, while validation-jma-08 diverged at generated index75. All recorded initial reference logits still satisfy2e-4 tolerance. At the common98-token prefix, Python chose 場合 over １ by9.5367431640625e-7; JavaScript rounded the two scores to a tie and chose the lower token ID. Common-prefix maximum absolute logit error is7.271766662597656e-6. The original outputs, failed pipeline log, strict evaluator and failure flags remain unchanged. The later auditor reports this failure rather than aborting the failure report; it does not relax the frozen language/parity criteria or rewrite output.', '', 'First-sentence passes stayed3/17 (original9:2/9); narrative first-sentence passes fell1/3 to0/3. Nonloop outputs rose1/17 to2/17, but meaningful full continuations stayed0/17. This is not evidence of established natural Japanese. No TEST generation or instruction tuning follows this failed gate.', '']
 (ROOT/'RESULTS.md').write_text('\n'.join(lines))
if __name__=='__main__':main()
